@[export: 'two_dimensional_string_matching']
pub fn two_dimensional_string_matching(input &i64,length usize,output &u8,capacity usize)i64{
 unsafe{if input==nil||length<6||length>132{return -1};rr:=input[0];cc:=input[1];hr:=input[2];wc:=input[3];if rr<1||rr>8||cc<1||cc>8||hr<1||hr>rr||wc<1||wc>cc{return -1};r:=int(rr);c:=int(cc);h:=int(hr);w:=int(wc);if length!=usize(4+r*c+h*w){return -1};mut text:=[]i64{len:r*c,init:0};mut pat:=[]i64{len:h*w,init:0};mut p:=4;for i in 0..(r*c){text[i]=input[p];p++;if text[i]<0||text[i]>3{return -1}};for i in 0..(h*w){pat[i]=input[p];p++;if pat[i]<0||pat[i]>3{return -1}}
 mut prefix:=[]int{len:h,init:0};for i in 1..h{mut q:=prefix[i-1];for q>0{mut equal:=true;for j in 0..w{if pat[i*w+j]!=pat[q*w+j]{equal=false}};if equal{break};q=prefix[q-1]};mut equal:=true;for j in 0..w{if pat[i*w+j]!=pat[q*w+j]{equal=false}};if equal{q++};prefix[i]=q}
 mut mark:=[]bool{len:512,init:false};for tr in 0..r{for col in 0..(c-w+1){for pr in 0..h{mut equal:=true;for j in 0..w{if text[tr*c+col+j]!=pat[pr*w+j]{equal=false}};mark[(tr*8+col)*8+pr]=equal}}}
 mut mr:=[]i64{len:64,init:0};mut mc:=[]i64{len:64,init:0};mut count:=0;for col in 0..(c-w+1){mut q:=0;for tr in 0..r{for q>0&&!mark[(tr*8+col)*8+q]{q=prefix[q-1]};if mark[(tr*8+col)*8+q]{q++};if q==h{mr[count]=i64(tr+1-h);mc[count]=i64(col);count++;q=prefix[h-1]}}};bytes:=8*(1+2*count);if output==nil||capacity<usize(bytes){return -2};values:=[]i64{len:1+2*count,init:0};values[0]=i64(count);for i in 0..count{values[1+2*i]=mr[i];values[2+2*i]=mc[i]};for i,x in values{bits:=u64(x);for b in 0..8{output[8*i+b]=u8((bits>>(8*b))&255)}};return i64(bytes)}
}
